</script><script>function hydrateImages(){
  document.querySelectorAll('[data-img]').forEach(function(el){var k=el.getAttribute('data-img');var s=window.AJYS_IMG[k];if(!s)return;
    if(el.tagName==='IMG')el.src=s;else el.style.backgroundImage="url('"+s+"')";});
  document.querySelectorAll('[data-logo]').forEach(function(el){el.src=window.AJYS_IMG['logo'];});
  document.querySelectorAll('[data-video]').forEach(function(el){el.src=window.AJYS_IMG['video'];});
}
function initHeader(){var h=document.querySelector('header.nav');var f=function(){h.classList.toggle('solid',window.scrollY>40);};f();window.addEventListener('scroll',f,{passive:true});}
function initMenu(){var b=document.querySelector('.hamburger'),m=document.querySelector('.mobile-menu'),o=document.querySelector('.menu-overlay'),c=document.querySelector('.menu-close');
  if(!b)return;var open=function(){m.classList.add('open');o.classList.add('open');},close=function(){m.classList.remove('open');o.classList.remove('open');};
  b.addEventListener('click',open);o.addEventListener('click',close);if(c)c.addEventListener('click',close);
  m.querySelectorAll('a').forEach(function(a){a.addEventListener('click',close);});}
function revealIn(scope){var els=scope.querySelectorAll('.reveal');
  if(!('IntersectionObserver' in window)){els.forEach(function(e){e.classList.add('in');});return;}
  var io=new IntersectionObserver(function(ents){ents.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target);}});},{threshold:.12});
  els.forEach(function(e){e.classList.remove('in');io.observe(e);});}
function initHeroBand(){var f=document.querySelector('[data-band]');if(!f)return;
  var sl=Array.prototype.slice.call(f.querySelectorAll('.slide')),dots=Array.prototype.slice.call(document.querySelectorAll('.hero-dots .dot')),i=0,t;
  function show(n){sl[i].classList.remove('on');if(dots[i])dots[i].classList.remove('on');i=(n+sl.length)%sl.length;sl[i].classList.add('on');if(dots[i])dots[i].classList.add('on');}
  function start(){t=setInterval(function(){show(i+1);},5000);}function reset(){clearInterval(t);start();}
  dots.forEach(function(d,x){d.addEventListener('click',function(){show(x);reset();});});
  sl[0].classList.add('on');if(dots[0])dots[0].classList.add('on');start();}
function initCarousel(){var rail=document.querySelector('[data-rail]');if(!rail)return;
  var prev=document.querySelector('[data-rail-prev]'),next=document.querySelector('[data-rail-next]');
  function amt(){var c=rail.querySelector('.work-card');return c?c.offsetWidth+24:320;}
  if(prev)prev.addEventListener('click',function(){rail.scrollBy({left:-amt(),behavior:'smooth'});});
  if(next)next.addEventListener('click',function(){rail.scrollBy({left:amt(),behavior:'smooth'});});}
function initSubscribe(){var f=document.querySelector('#subForm');if(!f)return;
  var re=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  f.addEventListener('submit',function(e){e.preventDefault();var i=f.querySelector('input');
    if(!re.test(i.value.trim())){i.classList.add('invalid');return;}
    /* TODO: POST email to a real list endpoint here */
    f.parentElement.innerHTML='<div class="sub-thanks">Thanks &mdash; you&rsquo;re on the list! \u2693</div>';});}
function initForm(){var form=document.querySelector('#contactForm');if(!form)return;var ok=document.querySelector('#formSuccess');
  var re=/^[^\s@]+@[^\s@]+\.[^\s@]+$/,req=['name','email','message'];
  form.querySelectorAll('input,textarea').forEach(function(i){i.addEventListener('input',function(){i.classList.remove('invalid');var e=i.parentElement.querySelector('.err');if(e)e.style.display='none';});});
  form.addEventListener('submit',function(e){e.preventDefault();var good=true;
    req.forEach(function(f){var inp=form.querySelector('[name='+f+']');var bad=!inp.value.trim();
      if(f==='email'&&inp.value.trim()&&!re.test(inp.value.trim()))bad=true;
      inp.classList.toggle('invalid',bad);var er=inp.parentElement.querySelector('.err');if(er)er.style.display=bad?'block':'none';if(bad)good=false;});
    if(!good)return;
    /* ===== TODO: POST to a real endpoint here ===== */
    form.style.display='none';if(ok)ok.style.display='block';});}
var ROUTES=['home','services','maintenance','reviews','contact'];
function showPage(name){if(ROUTES.indexOf(name)<0)name='home';
